import '../contact/Contact.css';
import { Form, Col, Row, Button } from 'react-bootstrap';
import Modal from '../../components/modals/Modal';
import { useState } from 'react';

const Contact = () => {
    const [OpenModal, setOpenModal] = useState(false);

    return (
        <>
            <Form className="container border border-primary border-2 rounded-3 col-sm-6 col-10 mt-2 text-white bg-info bg-opacity-10">
                <Row className="mb-3">
                    <Form.Group as={Col} controlId="firstName">
                        <Form.Label>First Name</Form.Label>
                        <Form.Control type="text" placeholder="First Name" required />
                    </Form.Group>

                    <Form.Group as={Col} controlId="lastName">
                        <Form.Label>Last Name</Form.Label>
                        <Form.Control type="text" placeholder="Last Name" required />
                    </Form.Group>
                </Row>

                <Form.Group className="mb-3" controlId="email">
                    <Form.Label>Email</Form.Label>
                    <Form.Control type="email" placeholder="Email" required />
                </Form.Group>

                <Form.Group className="mb-3" controlId="message">
                    <Form.Label>Your Message</Form.Label>
                    <Form.Control as="textarea" aria-label="With textarea" required/>
                </Form.Group>

                <div className="text-center">
                    <Button variant="danger" type="submit" onClick={() => {setOpenModal(true);}}>
                        Submit
                    </Button>
                    {OpenModal && <Modal closeModal = {setOpenModal}/>}
                </div>

            </Form>



        </>
    );
}

export default Contact;
